package com.paytrace.api;
import com.paytrace.payment.*; import com.paytrace.provider.ProviderFaultMode; import com.paytrace.investigation.*; import com.paytrace.webhook.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class PaymentController { private final PaymentService payments;private final InvestigationService investigations;private final PaymentEventRepository events;private final com.paytrace.integrity.IntegrityEngine integrity;private final com.paytrace.recovery.RecoveryPolicy recovery;private final WebhookInboxService webhooks; public PaymentController(PaymentService p,InvestigationService i,PaymentEventRepository e,com.paytrace.integrity.IntegrityEngine in,com.paytrace.recovery.RecoveryPolicy r,WebhookInboxService w){payments=p;investigations=i;events=e;integrity=in;recovery=r;webhooks=w;}
 @PostMapping("/payments") public ResponseEntity<PaymentView> create(@Valid @RequestBody CreatePaymentRequest request,@RequestHeader(value="Idempotency-Key",required=false) String key,@RequestHeader(value="X-Provider-Fault",defaultValue="NORMAL") ProviderFaultMode fault){return ResponseEntity.status(HttpStatus.CREATED).body(payments.create(request,key,fault));}
 @GetMapping("/payments") public List<PaymentView> list(){return payments.list();} @GetMapping("/payments/{id}") public PaymentView get(@PathVariable UUID id){return payments.get(id);} @PostMapping("/payments/{id}/investigate") public InvestigationView investigate(@PathVariable UUID id){return investigations.investigate(id);} @GetMapping("/payments/{id}/timeline") public List<PaymentEventEntity> timeline(@PathVariable UUID id){return events.findByPaymentIdOrderByOccurredAtAsc(id);}@GetMapping("/payments/{id}/integrity") public List<com.paytrace.integrity.InvariantResult> integrity(@PathVariable UUID id){return integrity.results(id);}@GetMapping("/payments/{id}/recovery") public Optional<com.paytrace.recovery.RecoveryRecommendation> recovery(@PathVariable UUID id){return recovery.latest(id);}
 @PostMapping("/webhooks/provider") public WebhookInboxService.WebhookOutcome webhook(@Valid @RequestBody ProviderWebhook hook){return webhooks.receive(hook);}
}
